  if (!win) { showNotification('弹窗被浏览器拦截，请允许弹窗后重试', 'error'); return; }

  var doc = win.document;
  doc.open();
  doc.write('<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Tip Distribution Report</title>');
