      if (!omitRoleSubEmployees && Array.isArray(cond.employees) && cond.employees.length) parts.push('员工: ' + cond.employees.join(', '));
      if (Array.isArray(cond.employeeRoles) && cond.employeeRoles.length) parts.push('员工筛选角色: ' + cond.employeeRoles.join(', '));
      if (Array.isArray(cond.employee) && cond.employee.length) parts.push('员工: ' + cond.employee.join(', '));
